/* wp-tracy-business: dark mode. The palette values WordPress prints on :root are fixed hex, so `color-scheme` alone flips nothing; the dark set restates every colour preset. Values are the Northgate source's own dark hook (html[data-theme=dark] in its inline stylesheet: body #101214/#ECEAE4, links #7FBFA6, and its rgb→hex map for surfaces, borders and text greys), read on the rendered page 14/09 and mapped token for token. The same set applies under prefers-color-scheme when the root element carries no data-theme, which is the 'auto' state. Two things the source keeps fixed in dark: the filled chrome button stays the brand green with white text (the chrome paints it from --wp--custom--tracy--brand--green), and the paper — the design's fixed white (#F5F3EE) that every ink and green surface carries its text in — stays paper: the source's hero title, figures, the closing call's title and the outline button's label all measure rgb(245,243,238) under dark (fast-5, 15/09), so brand paper is NOT restated here (14/09 moved it to #ECEAE4 and put the body's off-white on the bands). Brand ink IS restated, and not to the source's value: the source moves its bands to #0A0C0D, one step darker than the page, and at 390 the stats band and the footer were a 1px seam (fast-5 N-01ad58); a raised neutral (#1C2023) is the warm surface's own tone, so the hero met the services band edge to edge. The bands take the source's dark forest instead — #0C2B23, its own dark map for the deep green rgb(14,59,47) — a hue the page's neutrals never use, so a band is a block at any size (captions #8A8780 on it 4.1:1, copy #B9B5AC 7.3:1). The accent preset is mint here — a text and link colour — so nothing may fill a surface with it: filled buttons and active chips paint from --wp--custom--tracy--brand--green (white on #7FBFA6 is 2.1:1, measured 14/09). */
html { color-scheme: light dark; }
html[data-theme="light"] { color-scheme: light; }
html[data-theme="dark"] { color-scheme: dark; }
html[data-theme="dark"] {
  --wp--preset--color--bg: #101214;
  --wp--preset--color--surface: #191c1f;
  --wp--preset--color--surface-warm: #1c2023;
  --wp--preset--color--fg: #eceae4;
  --wp--preset--color--fg-2: #c7c4bd;
  --wp--preset--color--muted: #a9a6a0;
  --wp--preset--color--meta: #96938c;
  --wp--preset--color--border: #2c3033;
  --wp--preset--color--border-soft: #24282b;
  --wp--preset--color--accent: #7fbfa6;
  --wp--preset--color--accent-on: #ffffff;
  --wp--preset--color--accent-hover: #8fccb2;
  --wp--preset--color--accent-active: #9ed3bc;
  --wp--preset--color--success: #7fbfa6;
  --wp--preset--color--warn: #da5a2a;
  --wp--preset--color--danger: #f0a296;
  --wp--custom--tracy--brand--ink: #0c2b23;
  --wp--custom--tracy--brand--caption-light: #807d77;
  --wp--custom--tracy--brand--prose: #dddad3;
  --wp--custom--tracy--brand--header: #15181a;
  --wp--custom--elev--raised: 0 12px 32px rgba(0, 0, 0, 0.45);
}
@media (prefers-color-scheme: dark) {
  html:not([data-theme]) {
    --wp--preset--color--bg: #101214;
    --wp--preset--color--surface: #191c1f;
    --wp--preset--color--surface-warm: #1c2023;
    --wp--preset--color--fg: #eceae4;
    --wp--preset--color--fg-2: #c7c4bd;
    --wp--preset--color--muted: #a9a6a0;
    --wp--preset--color--meta: #96938c;
    --wp--preset--color--border: #2c3033;
    --wp--preset--color--border-soft: #24282b;
    --wp--preset--color--accent: #7fbfa6;
    --wp--preset--color--accent-on: #ffffff;
    --wp--preset--color--accent-hover: #8fccb2;
    --wp--preset--color--accent-active: #9ed3bc;
    --wp--preset--color--success: #7fbfa6;
    --wp--preset--color--warn: #da5a2a;
    --wp--preset--color--danger: #f0a296;
    --wp--custom--tracy--brand--ink: #0c2b23;
    --wp--custom--tracy--brand--caption-light: #807d77;
    --wp--custom--tracy--brand--prose: #dddad3;
    --wp--custom--tracy--brand--header: #15181a;
    --wp--custom--elev--raised: 0 12px 32px rgba(0, 0, 0, 0.45);
  }
}
/* The outline button's ring: ink in light, the source's dark grey (#3A3F43, its map for a 1px ink rule) in dark — fg would be near-white there. */
html[data-theme="dark"] .tracy .wp-block-button.is-style-outline .wp-block-button__link { border-color: #3a3f43; }
/* The active chip and the 404 search button: the source fills them ink, which in its dark map is #0A0C0D — one step darker than the page, so the active chip read as a hole and the search button as a slab (fast-5 N-3f47f8, N-38e704). 15/09 inverted them to paper on ink; that made them the brightest surfaces on the dark page (fast-6, scan white-surface ×5). They take the brand green with white text instead — the fill the chrome's own button keeps in dark, the second option the lens named — a block the page's neutrals never use. */
html[data-theme="dark"] .tracy-page-home .tracy-chips__all a, html[data-theme="dark"] .tracy.blog .tracy-chips__all a, html[data-theme="dark"] .tracy-chips .current-cat > a, html[data-theme="dark"] .tracy .wtb-hero--404 .wp-block-search__button { background: var(--wp--custom--tracy--brand--green); border-color: var(--wp--custom--tracy--brand--green); color: #ffffff; }
/* The source's own dark rule for its pictures (html[data-theme=dark] image-slot): content pictures dimmed, so a light photograph is not the brightest thing on a dark page (fast-5 N-196e7e). */
html[data-theme="dark"] .tracy .tracy-main img { filter: brightness(0.82) saturate(0.88); }
@media (prefers-color-scheme: dark) {
  html:not([data-theme]) .tracy .wp-block-button.is-style-outline .wp-block-button__link { border-color: #3a3f43; }
  html:not([data-theme]) .tracy-page-home .tracy-chips__all a, html:not([data-theme]) .tracy.blog .tracy-chips__all a, html:not([data-theme]) .tracy-chips .current-cat > a, html:not([data-theme]) .tracy .wtb-hero--404 .wp-block-search__button { background: var(--wp--custom--tracy--brand--green); border-color: var(--wp--custom--tracy--brand--green); color: #ffffff; }
  html:not([data-theme]) .tracy .tracy-main img { filter: brightness(0.82) saturate(0.88); }
}

/* The source's own markup keeps the colours its converter had no token for as literal rgb() in
   inline styles — the state tints and rules of its form and system messages, a chip outline, a
   lighter caption grey — and the source's dark hook maps exactly those by substring
   (`[style*=...]`). The same map here, to the presets where one exists (a declared preset is what
   the border scan accepts), otherwise to the source's own dark value (full-1, 15/09: the error
   input kept its pink fill and red rule in dark, the info note its light green, the chip its
   light outline — 60 rows). The style guide's colour swatches are NOT mapped: a swatch shows its
   colour. */
html[data-theme="dark"] [style*="background: rgb(232, 240, 235)"] { background-color: #14241e !important; }
html[data-theme="dark"] [style*="background: rgb(233, 242, 233)"] { background-color: #16261c !important; }
html[data-theme="dark"] [style*="background: rgb(251, 242, 226)"] { background-color: #2c2517 !important; }
html[data-theme="dark"] [style*="background: rgb(252, 243, 242)"] { background-color: #2b1a19 !important; }
html[data-theme="dark"] [style*="rgb(46, 125, 50)"] { border-color: var(--wp--preset--color--success) !important; }
html[data-theme="dark"] [style*="rgb(200, 137, 27)"] { border-color: var(--wp--preset--color--warn) !important; }
html[data-theme="dark"] [style*="rgb(192, 57, 43)"] { border-color: var(--wp--preset--color--danger) !important; }
html[data-theme="dark"] [style*="color: rgb(192, 57, 43)"] { color: var(--wp--preset--color--danger) !important; }
html[data-theme="dark"] [style*="color: rgb(31, 74, 34)"] { color: #a6d6a9 !important; }
html[data-theme="dark"] [style*="color: rgb(107, 74, 14)"] { color: #ddb769 !important; }
html[data-theme="dark"] [style*="color: rgb(122, 32, 22)"] { color: var(--wp--preset--color--danger) !important; }
html[data-theme="dark"] [style*="rgb(180, 175, 164)"] { border-color: var(--wp--preset--color--border) !important; }
html[data-theme="dark"] [style*="color: rgb(180, 175, 164)"] { color: #6e6b66 !important; }
html[data-theme="dark"] [style*="color: rgb(168, 164, 155)"] { color: #807d77 !important; }
/* The same lighter caption grey as a brand constant (brand.captionLight, #A8A49B) for the pattern CSS — a page link list dates its rows in it — takes the same dark value above, beside brand ink. */
@media (prefers-color-scheme: dark) {
  html:not([data-theme]) [style*="background: rgb(232, 240, 235)"] { background-color: #14241e !important; }
  html:not([data-theme]) [style*="background: rgb(233, 242, 233)"] { background-color: #16261c !important; }
  html:not([data-theme]) [style*="background: rgb(251, 242, 226)"] { background-color: #2c2517 !important; }
  html:not([data-theme]) [style*="background: rgb(252, 243, 242)"] { background-color: #2b1a19 !important; }
  html:not([data-theme]) [style*="rgb(46, 125, 50)"] { border-color: var(--wp--preset--color--success) !important; }
  html:not([data-theme]) [style*="rgb(200, 137, 27)"] { border-color: var(--wp--preset--color--warn) !important; }
  html:not([data-theme]) [style*="rgb(192, 57, 43)"] { border-color: var(--wp--preset--color--danger) !important; }
  html:not([data-theme]) [style*="color: rgb(192, 57, 43)"] { color: var(--wp--preset--color--danger) !important; }
  html:not([data-theme]) [style*="color: rgb(31, 74, 34)"] { color: #a6d6a9 !important; }
  html:not([data-theme]) [style*="color: rgb(107, 74, 14)"] { color: #ddb769 !important; }
  html:not([data-theme]) [style*="color: rgb(122, 32, 22)"] { color: var(--wp--preset--color--danger) !important; }
  html:not([data-theme]) [style*="rgb(180, 175, 164)"] { border-color: var(--wp--preset--color--border) !important; }
  html:not([data-theme]) [style*="color: rgb(180, 175, 164)"] { color: #6e6b66 !important; }
  html:not([data-theme]) [style*="color: rgb(168, 164, 155)"] { color: #807d77 !important; }
}
/* Three colours the dark map had to take back, all on the style guide (full-5). The Success rule
   and the Info rule both resolved to the accent mint, so two kinds of message differed only in
   their words (N-60c233). The Warning rule resolved to the warn preset, which in dark is still the
   brand Signal — a warning painted in the colour of the "Request a quote" button (N-4328c0). Both
   take the dark lift their own TEXT already took above (#A6D6A9 for the green, #DDB769 for the
   amber), one step more saturated because a 3px rule carries less colour than a line of type. And
   the newsletter card's input: the card is brand green in both schemes, so the field inside it
   keeps the source's own #0F3A2E instead of flipping to accent-hover's mint (N-d46e11). */
html[data-theme="dark"] [style*="border-left: 3px solid rgb(46, 125, 50)"] { border-left-color: var(--wp--custom--tracy--brand--success-rule) !important; }
html[data-theme="dark"] [style*="border-left: 3px solid rgb(200, 137, 27)"] { border-left-color: var(--wp--custom--tracy--brand--warning-rule) !important; }
html[data-theme="dark"] input[style*="background: var(--wp--preset--color--accent-hover)"] { background-color: #0f3a2e !important; }
/* The module position map and the colour swatches are the one drawing on the site that TEACHES the
   palette, so on that page ink stays ink — the same "literal" principle D24.28 kept for the Paper
   swatch. Everywhere else brand ink is #0C2B23 in dark (D24.18) so a band separates from the page;
   inside the map that mapping turned TOPBAR, the three footer cells and COPYRIGHT into a second
   green beside COMPONENT, and erased exactly the distinction the picture is drawn to make
   (N-7fcf8c). A hairline keeps the block visible on the card it sits on. */
html[data-theme="dark"] .tracy-page-stack--style-guide [style*="background: var(--wp--custom--tracy--brand--ink)"]:not([style*="grid-template-columns"]) { background-color: #14171a !important; box-shadow: inset 0 0 0 1px var(--wp--preset--color--border); }
@media (prefers-color-scheme: dark) {
  html:not([data-theme]) [style*="border-left: 3px solid rgb(46, 125, 50)"] { border-left-color: var(--wp--custom--tracy--brand--success-rule) !important; }
  html:not([data-theme]) [style*="border-left: 3px solid rgb(200, 137, 27)"] { border-left-color: var(--wp--custom--tracy--brand--warning-rule) !important; }
  html:not([data-theme]) input[style*="background: var(--wp--preset--color--accent-hover)"] { background-color: #0f3a2e !important; }
  html:not([data-theme]) .tracy-page-stack--style-guide [style*="background: var(--wp--custom--tracy--brand--ink)"]:not([style*="grid-template-columns"]) { background-color: #14171a !important; box-shadow: inset 0 0 0 1px var(--wp--preset--color--border); }
}
